letters=[]

for i in range(26):
    letter_str = ""
    
    alphabet_art_lines = ascii.splitlines()

    clip_start = i*16
    clip_end = (i+1)*16

    for alphabet_art_line in alphabet_art_lines:
        letter_str += alphabet_art_line[clip_start:clip_end] + "\n"

        letters.append(letter_str)

